window.docContents[32].resolve({"/Elementary-Functions/___4___37-Inverse-Hyperbolic-Functions/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___37-Inverse-Hyperbolic-Functions--___4___37-Inverse-Hyperbolic-Functions":{"contents":"The capitalized inverse hyperbolic functions are general multivalued values;\ntheir paths avoid branch points, use the stated principal square-root values\non the reference real sets, and continue the chosen branch. Arcsinh and\nArccsch have branch points at ±i; the other four general functions have\nbranch points at ±1. The lowercase functions are principal branches on the\nexplicit cut complements below. DLMF treats them as two-valued on their cuts\nand real on the remaining real axis. The Lean value-set declarations are an\nhonest equation-level specialization: they retain the defining hyperbolic\nequations but do not formalize path integrals or continuation data.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.37 Inverse Hyperbolic Functions","header":"§4.37 Inverse Hyperbolic Functions","id":"/Elementary-Functions/___4___37-Inverse-Hyperbolic-Functions/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___37-Inverse-Hyperbolic-Functions--___4___37-Inverse-Hyperbolic-Functions"},"/Gamma-Function/#chapter-5":{"contents":"Source: NIST Digital Library of Mathematical Functions, Chapter 5.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean","header":"5. Gamma Function","id":"/Gamma-Function/#chapter-5"}});